#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 256
#define MAX_SESSIONS 64
#define TOKEN_BYTES 32

typedef struct {
    char username[64];
    unsigned char token[TOKEN_BYTES];
    time_t expires;
    int active;
    int privilege_level;
} Session;

static Session sessions[MAX_SESSIONS];
static int session_count = 0;

static int constant_time_compare(const unsigned char *a, const unsigned char *b, int len) {
    /* Constant-time comparison to prevent timing attacks */
    if (len <= 0) return 1;  /* equal if nothing to compare */
    unsigned char result = 0;
    for (int i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

static int generate_token(unsigned char *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "r");
    if (!f) return -1;
    size_t read = fread(buf, 1, len, f);
    fclose(f);
    return (read == len) ? 0 : -1;
}

int create_session(const char *username, int privilege) {
    if (session_count >= MAX_SESSIONS) return -1;
    if (strlen(username) >= 63) return -1;

    Session *s = &sessions[session_count];
    strncpy(s->username, username, 63);
    s->username[63] = '\0';
    s->expires = time(NULL) + 3600;
    s->active = 1;
    s->privilege_level = privilege;

    if (generate_token(s->token, TOKEN_BYTES) != 0) return -1;
    session_count++;
    return session_count - 1;
}

typedef struct {
    int session_id;
    int token_length;
    unsigned char token_data[MAX_TOKEN_LEN];
} AuthRequest;

static int parse_auth_request(const unsigned char *raw, size_t raw_len, AuthRequest *req) {
    if (raw_len < 8) return -1;

    memcpy(&req->session_id, raw, 4);
    memcpy(&req->token_length, raw + 4, 4);

    /* Validate token_length fits in our buffer */
    if (req->token_length > MAX_TOKEN_LEN) return -1;

    if (raw_len < (size_t)(8 + req->token_length)) return -1;

    memcpy(req->token_data, raw + 8, req->token_length);
    return 0;
}

int validate_session(const AuthRequest *req) {
    if (req->session_id < 0 || req->session_id >= session_count) return -1;

    Session *s = &sessions[req->session_id];
    if (!s->active) return -1;
    if (time(NULL) > s->expires) {
        s->active = 0;
        return -1;
    }

    /* Verify token - compare only the bytes provided */
    if (req->token_length < TOKEN_BYTES) return -1;

    if (!constant_time_compare(s->token, req->token_data, req->token_length)) {
        return -1;
    }

    return s->privilege_level;
}

static void handle_admin_action(const char *action) {
    printf("[ADMIN] Executing: %s\n", action);
}

static void handle_user_action(const char *action) {
    printf("[USER] Executing: %s\n", action);
}

int process_request(const unsigned char *raw, size_t raw_len, const char *action) {
    AuthRequest req;
    memset(&req, 0, sizeof(req));

    if (parse_auth_request(raw, raw_len, &req) != 0) {
        fprintf(stderr, "Invalid request format\n");
        return -1;
    }

    int priv = validate_session(&req);
    if (priv < 0) {
        fprintf(stderr, "Authentication failed\n");
        return -1;
    }

    if (priv >= 2) {
        handle_admin_action(action);
    } else {
        handle_user_action(action);
    }
    return 0;
}

int main(int argc, char **argv) {
    /* Create a test session */
    int sid = create_session("admin", 2);
    if (sid < 0) { fprintf(stderr, "Failed to create session\n"); return 1; }

    printf("Session %d created for admin\n", sid);

    /* Simulate incoming request */
    if (argc > 1) {
        size_t input_len = strlen(argv[1]);
        if (input_len > 512) { fprintf(stderr, "Input too large\n"); return 1; }
        process_request((unsigned char*)argv[1], input_len, "list_users");
    }
    return 0;
}
